<?php get_header(); ?><main id="main-content" class="container section"><div class="section-head"><div><span class="eyebrow">Search</span><h1><?php printf(esc_html__('Results for “%s”','trendza'),esc_html(get_search_query())); ?></h1></div></div><?php if(have_posts()):?><div class="product-grid" data-trendza-search="<?php echo esc_attr(get_search_query()); ?>"><?php while(have_posts()):the_post();?><article class="product-card" data-trendza-product="<?php echo esc_attr(get_the_ID()); ?>"><a class="product-image" href="<?php the_permalink(); ?>"><?php if(has_post_thumbnail())the_post_thumbnail('medium_large');?></a><div class="product-body"><a class="product-title" href="<?php the_permalink(); ?>"><?php the_title();?></a><p class="muted"><?php echo esc_html(wp_trim_words(get_the_excerpt(),16));?></p></div></article><?php endwhile;?></div><?php the_posts_pagination();else:?><p class="muted">No matching products found. Try a different search.</p><?php endif;?></main><?php get_footer(); ?>
